function parseLedger(markdown) {
  // Brief 01: treat only the section whose heading line is exactly
  // `## Transaction Ledger` as authoritative. Locate with regex anchored at
  // whole heading lines; do not use substring search.
  const headingRe = /^## Transaction Ledger\s*$/m;
  const m = headingRe.exec(markdown);
  if (!m) return [];

  const slice = markdown.slice(m.index + m[0].length);

  // Keep the last non-provisional block per transaction id.
  const byId = new Map();
  const blocks = slice.split(/^### /m).slice(1);

  for (const block of blocks) {
    const lines = block.split("\n");
    const transactionId = (lines[0] || "").trim();
    if (!transactionId.startsWith("TXN-")) continue;

    // Ignore provisional blocks (case-insensitive).
    if (/^\s*provisional:\s*true\s*$/gim.test(block)) continue;

    const row = { transaction_id: transactionId };
    for (const line of lines) {
      const trimmed = line.trim();
      if (/^amount\s*:/i.test(trimmed)) {
        row.amount = Number(trimmed.split(":")[1].trim());
      } else if (/^owner\s*:/i.test(trimmed)) {
        row.owner = trimmed.split(":")[1].trim();
      } else if (/^status\s*:/i.test(trimmed)) {
        row.status = trimmed.split(":")[1].trim();
      } else if (/^date\s*:/i.test(trimmed)) {
        row.date = trimmed.split(":")[1].trim();
      }
    }

    byId.set(transactionId, row);
  }

  return [...byId.values()];
}

module.exports = { parseLedger };
