const STATUS_ORDER = { pending: 0, approved: 1, rejected: 2, reversed: 3 };

function isGteDate(a, b) {
  // YYYY-MM-DD lexicographic comparison works.
  return String(a) >= String(b);
}

function normalizeStatus(s) {
  return String(s || "").trim().toLowerCase();
}

function shouldApplyEmailStatus({ email, ledgerDate, currentStatus }) {
  // Brief 03: if sent exists, apply only if sent >= ledger date.
  if (email.sent && !isGteDate(email.sent, ledgerDate)) return false;

  // Brief 02: apply only if precedence increases.
  const next = normalizeStatus(email.status);
  const cur = normalizeStatus(currentStatus);
  return (STATUS_ORDER[next] ?? -1) > (STATUS_ORDER[cur] ?? -1);
}

