    const prev = winnersByKey.get(key);
    if (!prev) {
      winnersByKey.set(key, notice);
      continue;
    }
    if (String(notice.effective) > String(prev.effective)) {
      winnersByKey.set(key, notice);
    } else if (String(notice.effective) === String(prev.effective)) {
      // deterministic tie-break
      if (String(notice.notice_id) > String(prev.notice_id)) winnersByKey.set(key, notice);
    }
  }

  const winners = [...winnersByKey.values()].sort((a, b) => {
    if (a.notice_id < b.notice_id) return -1;
    if (a.notice_id > b.notice_id) return 1;
    return 0;
  });

  const report = [];
  const statusChangedById = new Set();
  const effectiveOverrideById = new Map();

  for (const notice of winners) {
    const target = byId.get(notice.transaction_id);
    if (!target) continue;

    let previousValue = "";
    if (notice.field === "owner") {
      previousValue = String(target.owner ?? "");
      target.owner = notice.value;
    } else if (notice.field === "status") {
      previousValue = String(target.status ?? "");
      target.status = normalizeStatus(notice.value);
      statusChangedById.add(notice.transaction_id);
      effectiveOverrideById.set(notice.transaction_id, notice.effective);
    } else if (notice.field === "date") {
      previousValue = String(target.date ?? "");
      target.date = notice.value;
      effectiveOverrideById.set(notice.transaction_id, notice.effective);
